'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
async function qualifyInventoryFullAppBrowser({origin,user,password,root,readCounts,verify}){
 const browser=await require('./secureshopAnalyticsBrowserOwner').launchOwnedAnalyticsBrowser(root,'inventoryapp');let page,frame,cdp,failure,committed;const posts=[],gets=[],errors=[],blocked=[];
 try{
  page=await browser.newPage();await page.setViewport({width:1440,height:1100});await require('./fullBackendRenderedSecureShop').configurePage(page,origin,blocked,errors);await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);
  page.on('request',r=>{const p=new URL(r.url()).pathname;if(p.includes('/merchant/inventory/')){if(r.method()==='POST')posts.push(JSON.parse(r.postData()));else gets.push(p);}});
  await page.goto(origin+'/workshop-login',{waitUntil:'domcontentloaded'});await page.waitForSelector('input[placeholder="Enter your username"]');await page.type('input[placeholder="Enter your username"]',user.username);await page.type('input[placeholder="Enter your password"]',password);await page.click('button[type="submit"]');await page.waitForFunction(()=>Boolean(localStorage.getItem('token'))&&location.pathname!=='/workshop-login');await page.goto(origin+'/workshop/secureshop');
  const getFrame=async()=>{const el=await page.waitForSelector('iframe[title="SecureShop workshop"]'),f=await el.contentFrame();await f.waitForFunction(()=>window.origin==='null');return f;};frame=await getFrame();
  const login=async username=>{await frame.waitForFunction(()=>document.querySelector('#ss-login-user')||document.querySelector('a[href="/secureshop/login"]'));if(!await frame.$('#ss-login-user'))await frame.click('a[href="/secureshop/login"]');await frame.waitForSelector('#ss-login-user');await frame.type('#ss-login-user',username);await frame.type('#ss-login-pw','student123');await frame.click('button[type="submit"]');await frame.waitForSelector('[aria-label="Account menu"]');};
  const logout=async()=>{await frame.click('[aria-label="Account menu"]');const h=await frame.evaluateHandle(()=>[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Sign out'));assert.ok(h.asElement());await h.asElement().click();};
  const couponProbe=()=>frame.evaluate(async()=>{const cart=await fetch('/api/secureshop/cart'),value=await cart.json();const coupon=await fetch('/api/secureshop/cart/apply-coupon',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code:'CONTROLLED-NONEXISTENT',operationId:crypto.randomUUID()})});return{cartStatus:cart.status,keys:Object.keys(value).sort(),couponStatus:coupon.status};});
  await login('student_customer');const couponBefore=await couponProbe();assert.equal(couponBefore.cartStatus,200);assert.equal(couponBefore.couponStatus,503,'Unprovisioned coupon executor must remain fail-closed');await logout();await login('student_merchant');

  const overview=async()=>{await frame.waitForSelector('a[href="/secureshop/merchant"]');await frame.click('a[href="/secureshop/merchant"]');await frame.waitForSelector('#inventory-message');await frame.waitForFunction(()=>!document.querySelector('section[aria-label="inventory assistant"]').innerText.includes('Inventory assistant unavailable'));};await overview();
  const click=async label=>{const h=await frame.evaluateHandle(label=>[...document.querySelectorAll('section[aria-label="inventory assistant"] button')].find(b=>b.textContent.trim()===label&&!b.disabled),label);const b=h.asElement();assert.ok(b,'Enabled '+label);await page.$eval('iframe[title="SecureShop workshop"]',e=>e.scrollIntoView({block:'start',behavior:'instant'}));await b.evaluate(e=>e.scrollIntoView({block:'center',behavior:'instant'}));const box=await b.boundingBox();assert.ok(box&&box.y>=0&&box.y+box.height<=1100,'Inventory control reachable');await b.click();};
  assert.equal(await frame.$eval('#inventory-access',element=>element.value),'read');await frame.select('#inventory-access','write');assert.equal(await frame.$eval('#inventory-access',element=>element.value),'write');
  const message='Read stock, then set product 1 stock to 4 for this controlled transport test.';await frame.type('#inventory-message',message);
  cdp=await page.createCDPSession();let syntheticStatus=null;
  cdp.on('Fetch.requestPaused',async e=>{try{const url=new URL(e.request.url);if(url.pathname.endsWith('/run')&&!committed&&e.responseStatusCode===200){const body=await cdp.send('Fetch.getResponseBody',{requestId:e.requestId});committed=JSON.parse(Buffer.from(body.body,body.base64Encoded?'base64':'utf8').toString());assert.equal(committed.status,'completed');await cdp.send('Fetch.fulfillRequest',{requestId:e.requestId,responseCode:502,responseHeaders:[{name:'content-type',value:'application/json'}],body:Buffer.from('{"error":"controlled response loss"}').toString('base64')});}else if(syntheticStatus&&url.pathname.includes('/operations/')){await cdp.send('Fetch.fulfillRequest',{requestId:e.requestId,responseCode:200,responseHeaders:[{name:'content-type',value:'application/json'}],body:Buffer.from(JSON.stringify({requestId:committed.requestId,status:syntheticStatus})).toString('base64')});}else await cdp.send('Fetch.continueRequest',{requestId:e.requestId});}catch(e2){failure=e2;await cdp.send('Fetch.failRequest',{requestId:e.requestId,errorReason:'Failed'}).catch(()=>{});}});
  await cdp.send('Fetch.enable',{patterns:[{urlPattern:origin+'/api/secureshop/merchant/inventory/*',requestStage:'Response'}]});
  await click('Run inventory');await frame.waitForFunction(()=>document.querySelector('section[aria-label="inventory assistant"]').innerText.includes('Inventory outcome unresolved'));if(failure)throw failure;assert.ok(committed);assert.equal(posts.length,1);const before=readCounts();assert.equal(before.judgeCalls,0);await verify(committed.requestId);
  await page.reload();frame=await getFrame();await frame.waitForSelector('[aria-label="Account menu"]');await overview();await frame.waitForFunction(()=>[...document.querySelectorAll('button')].some(b=>b.textContent==='Check saved request'));
  for(const status of ['pending','uncertain','not_found']){syntheticStatus=status;await click('Check saved request');await frame.waitForFunction(status=>document.querySelector('section[aria-label="inventory assistant"]').innerText.includes(status==='not_found'?'No saved result was found':status),{},status);assert.equal(posts.length,1);assert.deepEqual(readCounts(),before);}
  syntheticStatus=null;await frame.type('#inventory-message',message);await click('Retry same request');await frame.waitForFunction(()=>document.querySelector('section[aria-label="inventory assistant"]').innerText.includes('Controlled inventory request completed'));assert.equal(posts.length,2);assert.deepEqual(posts[0],posts[1]);assert.deepEqual(readCounts(),before);assert.ok(gets.filter(p=>p.endsWith('/operations/'+committed.requestId)).length>=3);await frame.waitForSelector('section[aria-label="inventory assistant"] table');await page.screenshot({path:path.join(root,'inventory-full-app-completed.png'),fullPage:true});
  await cdp.send('Fetch.disable');await cdp.detach();cdp=null;
  const status=await frame.evaluate(async()=>{const r=await fetch('/api/secureshop/merchant/listings/readiness');return (await r.json()).ready;});assert.equal(status,true,'Existing Listings remains ready');
  const product=committed.operations.find(x=>x.action==='stock_levels').result.items.find(x=>x.productId===1);assert.ok(product);
  await logout();await login('student_customer');const stale=await frame.evaluate(async id=>(await fetch('/api/secureshop/merchant/inventory/operations/'+id)).status,committed.requestId);assert.ok([403,409].includes(stale));
  await frame.waitForSelector('input[aria-label="Search products"]');await frame.type('input[aria-label="Search products"]',product.name);await(await frame.$('input[aria-label="Search products"]')).press('Enter');await frame.waitForSelector('a[href="/secureshop/product/1"]');await frame.click('a[href="/secureshop/product/1"]');await frame.waitForFunction(()=>document.body.innerText.toLowerCase().includes('4 in stock'));
  const readback=await frame.evaluate(async()=>{const r=await fetch('/api/secureshop/products/1');return{status:r.status,body:await r.json()};});assert.equal(readback.status,200);assert.equal((readback.body.product||readback.body).stock_quantity,4);await page.screenshot({path:path.join(root,'inventory-full-app-customer.png'),fullPage:true});assert.deepEqual(await couponProbe(),couponBefore);
  const resetResponse=page.waitForResponse(r=>new URL(r.url()).pathname.endsWith('/reset')&&r.request().method()==='POST');const h=await page.evaluateHandle(()=>[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Reset launch'&&!b.disabled));assert.ok(h.asElement());await h.asElement().evaluate(e=>e.scrollIntoView({block:'center',behavior:'instant'}));await h.asElement().click();assert.equal((await resetResponse).status(),200);await page.waitForFunction(()=>!document.body.innerText.includes('Resetting…'));frame=await getFrame();const denied=await frame.evaluate(async id=>(await fetch('/api/secureshop/merchant/inventory/operations/'+id)).status,committed.requestId);assert.ok([401,403,409,503].includes(denied),'Reset recovery must receive an explicit platform denial');assert.deepEqual(errors,[]);assert.deepEqual(blocked,[]);if(failure)throw failure;
  return{status:'passed',actualModelCalls:0,judgeCalls:0,controlledProvider:true,modelShapedMetadataOverride:true,syntheticRecoveryStatuses:['pending','uncertain','not_found'],realJwt:true,opaqueFrame:true,sameRequestId:committed.requestId,postCount:2,actorReexecuted:false,resetRequested:true,oldRecoveryStatus:denied,existingListingsReady:true,customerStockReadback:4,couponReadinessUnchanged:couponBefore,changedPersonaDenied:true,counts:readCounts()};
 }catch(error){fs.writeFileSync(path.join(root,'inventory-full-app-browser-error.json'),JSON.stringify({message:error.message,posts,gets,errors,blocked}),{mode:0o600});if(page)await page.screenshot({path:path.join(root,'inventory-full-app-failure.png'),fullPage:true}).catch(()=>{});throw error;}finally{if(cdp)await cdp.detach().catch(()=>{});await browser.close();}
}
module.exports={qualifyInventoryFullAppBrowser};
